function createKeyStore() {
  const entries = new Map();
  return {
    handle(userId, key, fingerprint, work) {
      const id = `${userId}:${key}`;
      const entry = entries.get(id);
      if (entry && entry.fingerprint !== fingerprint) return { status: 422 };
      if (entry) return { ...entry.result, replayed: true };
      const result = work();
      entries.set(id, { fingerprint, result });
      return result;
    },
  };
}

const store = createKeyStore();
let transfers = 0;
const work = () => ({ status: 201, transferId: ++transfers });
console.log(store.handle(1, "k1", "ada->bola 10000", work));
console.log(store.handle(1, "k1", "ada->bola 10000", work));
