const accounts = {
  1: { owner: 1, status: "active", balance: 5000000 },
  2: { owner: 2, status: "active", balance: 500000 },
  3: { owner: 3, status: "frozen", balance: 2000000 },
};

function checkTransfer({ userId, from, to, amountKobo }, accounts) {
  if (!Number.isSafeInteger(amountKobo) || amountKobo <= 0) return "invalid_amount";
  if (from === to) return "same_account";
  const sender = accounts[from];
  if (!sender || sender.owner !== userId) return "account_not_found";
  if (sender.status !== "active") return "account_not_active";
  const recipient = accounts[to];
  if (!recipient || recipient.status !== "active") return "recipient_unavailable";
  if (sender.balance < amountKobo) return "insufficient_funds";
  return "ok";
}

const tries = [
  { userId: 1, from: 1, to: 2, amountKobo: 1000000 },
  { userId: 1, from: 1, to: 2, amountKobo: 0.5 },
  { userId: 2, from: 1, to: 2, amountKobo: 100 },
  { userId: 3, from: 3, to: 1, amountKobo: 100 },
  { userId: 1, from: 1, to: 99, amountKobo: 100 },
  { userId: 2, from: 2, to: 1, amountKobo: 900000 },
];
console.log(tries.map((t) => checkTransfer(t, accounts)));

