async function send(key) {
  keysSeen.push(key);
  const outcome = outcomes.shift();
  if (outcome === "network") throw new Error("socket hang up");
  return outcome;
}

async function sendWithRetries(send, maxAttempts) {
  const key = "intent-1";
  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      const status = await send(key);
      console.log(`attempt ${attempt}: ${status}`);
      if (status !== 409 && status !== 429 && status < 500) return status;
    } catch (error) {
      console.log(`attempt ${attempt}: network error`);
    }
  }
  return "unknown";
}

console.log(await sendWithRetries(send, 5));
