const row = { status: "in_progress", lockedUntil: 30000, lockId: "A" };

function begin(row, now, lockMs) {
  if (row.status === "completed") return "replay";
  if (row.lockedUntil > now) return "409";
  row.lockedUntil = now + lockMs;
  row.lockId = row.lockId + "'";
  return `proceed ${row.lockId}`;
}

