questions.solution:
const before = { ada: 5000000, bola: 500000, chidi: 2000000 };
const goodAfter = { ada: 4000000, bola: 1500000, chidi: 2000000 };
const badAfter = { ada: 4000000, bola: 500000, chidi: 2000000 };

function checkInvariant(before, after) {
  const total = (b) => Object.values(b).reduce((sum, kobo) => sum + kobo, 0);
  const naira = (kobo) => `₦${(kobo / 100).toLocaleString("en-NG")}`;
  const difference = total(after) - total(before);
  if (difference === 0) console.log(`ok: total ${naira(total(after))}`);
  else console.log(`broken: ${naira(Math.abs(difference))} ${difference < 0 ? "went missing" : "appeared"}`);
}

checkInvariant(before, goodAfter);
checkInvariant(before, badAfter);
